// Reference solution
function notModified(ifNoneMatch, etag) {
  if (!ifNoneMatch || !etag) return false;
  if (ifNoneMatch.trim() === '*') return true;
  const strip = (t) => t.trim().replace(/^W\//, '');
  return ifNoneMatch.split(',').map(strip).includes(strip(etag));
}

